def get_direction(val):
    if val % 3 == 0:
        return -1, 0  # UP vertical
    elif val == 1:
        return -1, 2  # NE diagonal
    else:
        return 0, -1  # LEFT horizontal

def get_num_steps(orig_i, orig_j, dr, dc):
    """Correctly calculate number of steps before hitting boundary"""
    if dr != 0 and dc == 0:  # Vertical UP (dr = -1)
        # Can take up to orig_i steps before hitting row 0
        return orig_i
    elif dr == 0 and dc != 0:  # Horizontal LEFT (dc = -1)
        # Can take up to orig_j steps before hitting col 0
        return orig_j
    else:  # Diagonal - need intersection of both boundaries
        # For (-1, +2) or similar: find when either bound is hit
        rows_until_hit = abs(orig_i // abs(dr))  # steps until row < 0
        if dc > 0:
            cols_until_hit = abs((10 - orig_j) // abs(dc))
        else:
            cols_until_hit = abs(orig_j // abs(dc))
        return min(rows_until_hit, cols_until_hit)

def get_intermediate_value(val, d, direction):
    if direction == 'vertical':
        return 5
    elif direction == 'horizontal':
        return 5 if d % 2 == 1 else 4
    else:
        return val + 4

