    result = np.zeros(grid_shape, dtype=int)

    for orig_i, orig_j, val in input_points:
        dr, dc = get_direction(val)
        num_steps = get_num_steps(orig_i, orig_j, dr, dc)

        print(f"{val} at ({orig_i},{orig_j}): dir=({dr},{dc}), {num_steps} steps")

